#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# scripts/saas_keys.sh (goal 57 M5): the owner makes a Google OAuth "Desktop app" client and a Stripe test-mode key and
# Pro price; the values go to ~/.config/omxcode/saas.env (mode 0600), which scripts/saas.sh run and scripts/check M5
# read. Nothing here prints a secret.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
mkdir -p -m 700 "$HOME/.config/omxcode"
ENV_FILE="$HOME/.config/omxcode/saas.env"
[ -e "$ENV_FILE" ] && chmod 600 "$ENV_FILE"  # (an older file keeps its mode under write_env: make it private first)
stripe() {  # stripe <path> <form args…>: Stripe's API with the key on stdin, never on the command line
  printf 'user = "%s:"\n' "$STRIPE_SECRET_KEY" | curl -fsS -K - "https://api.stripe.com$1" "${@:2}"
}

banner "omxcode SaaS: Google sign-in, Stripe test keys, SMTP"

stage "Google: a Cloud project"
say "Sign-in needs an OAuth client, which lives in a Google Cloud project."
open_url "https://console.cloud.google.com/projectcreate"
step "Name it (e.g. omxcode-saas) and press Create. Already have one for this? Pick it in the top bar instead."
step "Wait for the notification that it's ready, and make sure it's selected in the top bar."
pause "Done? Press Enter"

stage "Google: the consent screen (Google Auth Platform)"
open_url "https://console.cloud.google.com/auth/overview"
step "Press Get started (if shown). App name: omxcode SaaS. User support email: yours. Next."
step "Audience: External. Next. Contact email: yours. Agree, Create."
open_url "https://console.cloud.google.com/auth/audience"
step "Under Test users press Add users and add your own Google address (the app stays in Testing: only test users sign in)."
note "Scopes: openid, email and profile are basic scopes; nothing to add under Data access."
pause "Done? Press Enter"

stage "Google: a Desktop app client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Desktop app. Name: omxcode saas. Press Create."
note "A Desktop client lets the server's loopback callback (http://127.0.0.1:<any port>/auth/callback) through (D-5705)."
step "Copy the Client ID (ends .apps.googleusercontent.com)."
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
until [[ "$GOOGLE_CLIENT_ID" == *.apps.googleusercontent.com ]]; do
  warn "that doesn't end in .apps.googleusercontent.com"
  ask GOOGLE_CLIENT_ID "Paste the Client ID:"
done
step "Copy the Client secret (starts GOCSPX-; the client's page shows it, or Download JSON)."
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

stage "Stripe: a test-mode secret key"
say "Test mode only: no real money moves, and the server refuses its test hook with a live key."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Make sure the dashboard shows Test mode (or a sandbox), then press Reveal test key on the Secret key row and copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key, sk_test_… (hidden):"
until [[ "$STRIPE_SECRET_KEY" == sk_test_* ]]; do
  warn "that isn't a test-mode secret key (it must start with sk_test_; never paste a live key here)"
  ask_secret STRIPE_SECRET_KEY "Paste the secret key, sk_test_… (hidden):"
done
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"

stage "Stripe: the Pro price"
say "The checkout sells one recurring price: Pro, monthly, in test mode."
current=$(_existing STRIPE_PRICE_PRO || true)
if [[ -n "$current" ]] && ! confirm "A Pro price is saved already. Make a new one?"; then
  note "keeping the saved price"
elif confirm "Create it for you now through Stripe's API (product \"omxcode Pro\", \$9.00 a month, test mode)?"; then
  product=$(stripe /v1/products -d name="omxcode Pro" | grep -o '"id": *"prod_[A-Za-z0-9]*"' | head -1 | grep -o 'prod_[A-Za-z0-9]*') || product=""
  price=""
  if [[ -n "$product" ]]; then
    price=$(stripe /v1/prices -d product="$product" -d unit_amount=900 -d currency=usd -d "recurring[interval]=month" | grep -o '"id": *"price_[A-Za-z0-9]*"' | head -1 | grep -o 'price_[A-Za-z0-9]*') || price=""
  fi
  if [[ -n "$price" ]]; then
    write_env STRIPE_PRICE_PRO "$price"
  else
    warn "Stripe didn't make it (is the key right?): make it by hand below"
  fi
fi
if [[ -z "$(_existing STRIPE_PRICE_PRO || true)" ]]; then
  open_url "https://dashboard.stripe.com/test/products/create"
  step "Name: omxcode Pro. Pricing: Recurring, Monthly, any amount (e.g. 9.00). Add product."
  step "On the product's page, copy the price's ID from its menu (starts price_)."
  ask STRIPE_PRICE_PRO "Paste the price ID:"
  until [[ "$STRIPE_PRICE_PRO" == price_* ]]; do
    warn "a price ID starts with price_"
    ask STRIPE_PRICE_PRO "Paste the price ID:"
  done
  write_env STRIPE_PRICE_PRO "$STRIPE_PRICE_PRO"
fi

stage "Stripe: the customer portal"
say "Manage billing opens Stripe's customer portal; in test mode it needs saving once before it works."
open_url "https://dashboard.stripe.com/test/settings/billing/portal"
step "Check Test mode, allow customers to update payment methods, cancel subscriptions (at the end of the period), see invoices."
step "Press Save (or Activate test link)."
pause "Done? Press Enter"

stage "Email: an SMTP account"
say "Welcome and invitation emails go out over SMTP: any provider gives you a host, a port, a user and a password"
say "(Postmark, Resend, Amazon SES, Fastmail, Gmail with an app password)."
note "Implicit TLS is port 465 (SMTP_TLS=implicit); STARTTLS is port 587 (SMTP_TLS=starttls). Both are checked."
ask SMTP_HOST "SMTP host (e.g. smtp.postmarkapp.com):"
until [[ "$SMTP_HOST" =~ ^[A-Za-z0-9.-]+$ ]]; do
  warn "a host name, letters, digits, dots and dashes only"
  ask SMTP_HOST "SMTP host:"
done
ask SMTP_TLS "TLS: implicit (port 465) or starttls (port 587)?"
until [[ "$SMTP_TLS" == implicit || "$SMTP_TLS" == starttls ]]; do
  warn "type implicit or starttls"
  ask SMTP_TLS "TLS: implicit or starttls?"
done
default_port=465; [[ "$SMTP_TLS" == starttls ]] && default_port=587
ask SMTP_PORT "Port (Enter for $default_port):"
[[ -z "$SMTP_PORT" ]] && SMTP_PORT=$default_port
until [[ "$SMTP_PORT" =~ ^[0-9]+$ ]]; do
  warn "a port is a number"
  ask SMTP_PORT "Port:"
done
ask SMTP_USER "SMTP user name:"
ask_secret SMTP_PASSWORD "SMTP password or API token (hidden):"
ask SMTP_FROM "Send as (e.g. omxcode SaaS <hello@yourdomain.com>; the provider must allow this sender):"
until [[ "$SMTP_FROM" == *@* ]]; do
  warn "it needs an address"
  ask SMTP_FROM "Send as:"
done
for k in SMTP_HOST SMTP_PORT SMTP_TLS SMTP_USER SMTP_PASSWORD SMTP_FROM; do write_env "$k" "${!k}"; done

stage "Check it"
say "The live check asks Google about the client, makes a real test-mode checkout and pays it with Stripe's 4242 card."
if confirm "Run goal 57's live check M5 now (about a minute)?"; then
  (cd "$(dirname "$0")/.." && pixi run python docs/goals/57-check.py M5) || warn "M5 didn't pass: its line says why"
  pause "Press Enter"
fi
note "Then sign in with Google once by hand: scripts/saas.sh run, and the app (scripts/build.sh saas linux;"
note "SAAS_SERVER=http://127.0.0.1:8000 build/saas/linux/saas) → Sign in with Google."

chmod 600 "$ENV_FILE"
finish
}

run_wizard "$@"; exit
